export function technologyTierIndex(tier: TechnologyTier | undefined): number { return TIER_ORDER.indexOf(tier ?? "Foundation"); }
export function baselineStateIndex(tier: TechnologyTier | undefined, retrofitLevel = 0): number { return technologyTierIndex(tier) * 3 + Math.max(0, Math.min(2, Math.floor(retrofitLevel))); }
export function getBaselineRow(systemId: string): RatingRow | undefined { return SYSTEM_BASELINES.find(row => row.id === systemId); }
export function getBaselineRating(systemId: string, tier: TechnologyTier | undefined, retrofitLevel = 0): number { const value = getBaselineRow(systemId)?.values[baselineStateIndex(tier, retrofitLevel)]; return typeof value === "number" ? value : 0; }
export function getAdditionalMetricRow(systemId: string, metricIncludes: string): RatingRow | undefined { const needle = metricIncludes.toLowerCase(); return ADDITIONAL_METRICS.find(row => row.id === systemId && row.metric.toLowerCase().includes(needle)); }
export function getAdditionalRating(systemId: string, metricIncludes: string, tier: TechnologyTier | undefined, retrofitLevel = 0): number { const value = getAdditionalMetricRow(systemId, metricIncludes)?.values[baselineStateIndex(tier, retrofitLevel)]; return typeof value === "number" ? value : 0; }
export function getSupportProfile(systemId: string): SupportProfile | undefined { return SUPPORT_PROFILES.find(row => row.id === systemId); }
export function getRepairOptions(systemId: string): RepairOption[] { return REPAIR_OPTIONS.filter(option => option.systemId === systemId); }
export function getRepairOption(systemId: string, optionId: string): RepairOption | undefined { return REPAIR_OPTIONS.find(option => option.systemId === systemId && option.id === optionId); }
export function effectiveRepairTierIndex(targetTier: TechnologyTier | undefined, requiredSystems: string[], selected: Record<string, TechnologyTier>): number { return Math.min(technologyTierIndex(targetTier), ...requiredSystems.map(id => selected[id] ? technologyTierIndex(selected[id]) : 0)); }
export function getRepairEffectValue(option: RepairOption, effectiveTierIndex: number): number { const value = option.effects[Math.max(0, Math.min(3, effectiveTierIndex))]; return typeof value === "number" ? value : 0; }
export function getRetrofitInstallation(systemId: string, tier: TechnologyTier | undefined, retrofitLevel: number): RetrofitInstallation | undefined { const techTier = tier ?? "Foundation"; const progress = retrofitLevel === 0 ? "0/2" : "1/2"; return RETROFIT_INSTALLATIONS.find(row => row.systemId === systemId && row.tier === techTier && row.currentProgress === progress); }
export function interpolateSolarProfile(day: number) {
  const profile = LEVEL1_ENVIRONMENT.solarProfile;
  const bounded = Math.max(0, Math.min(14, day));
  const lower = profile[Math.floor(bounded)];
  const upper = profile[Math.min(profile.length - 1, Math.ceil(bounded))];
  const mix = bounded - Math.floor(bounded);
  return {
    sunlightGeometry: lower.sunlightGeometry + (upper.sunlightGeometry - lower.sunlightGeometry) * mix,
    irradianceWm2: lower.irradianceWm2 + (upper.irradianceWm2 - lower.irradianceWm2) * mix,
    groundTempC: lower.groundTempC + (upper.groundTempC - lower.groundTempC) * mix,
    cellTempC: lower.cellTempC + (upper.cellTempC - lower.cellTempC) * mix,
    cellTemperatureLoss: lower.cellTemperatureLoss + (upper.cellTemperatureLoss - lower.cellTemperatureLoss) * mix,
  };
}
